    'tl.support.s02_title': 'Nelerde yard\u0131mc\u0131 olabiliriz',
    'tl.support.s02_li1': 'Giri\u015f, \u015fifre s\u0131f\u0131rlama ve e-posta do\u011frulama',
    'tl.support.s02_li2': 'Abonelik planlar\u0131, faturalama ve App Store sat\u0131n al\u0131mlar\u0131',
